'use client';

import * as React from 'react';
import { cn } from '@/lib/utils';
import {
  addMonths,
  calendarWeeks,
  formatDateLabel,
  monthLabel,
  moveDateKey,
  parseDateKey,
  todayKey,
  weekdayLabels,
  type CalendarMove,
} from '../../utils/date';
import { Button } from '../button';

export type CalendarProps = {
  /** Controlled ISO date key (`YYYY-MM-DD`). */
  value?: string;
  /** Uncontrolled initial date key. */
  defaultValue?: string;
  /** Called with the ISO key when a day is chosen. */
  onValueChange?: (value: string) => void;
  /** Earliest selectable day, inclusive. */
  min?: string;
  /** Latest selectable day, inclusive. */
  max?: string;
  /** Override "today" (testing and server-rendered determinism). */
  today?: string;
  /** BCP-47 locale for month and weekday labels. */
  locale?: string;
  /** 0 starts the week on Sunday, 1 on Monday. */
  weekStartsOn?: 0 | 1;
  /** Block individual days beyond min/max. */
  isDateDisabled?: (value: string) => boolean;
  /** Show leading/trailing days from the neighbouring months. */
  showOutsideDays?: boolean;
  /** Focus the active day when the calendar mounts or opens. */
  autoFocus?: boolean;
  disabled?: boolean;
  className?: string;
  'aria-label'?: string;
};

const MOVES: Record<string, CalendarMove> = {
  ArrowLeft: 'left',
  ArrowRight: 'right',
  ArrowUp: 'up',
  ArrowDown: 'down',
  Home: 'home',
  End: 'end',
  PageUp: 'pageup',
  PageDown: 'pagedown',
};

/**
 * Month grid with ISO date keys and full keyboard support. Controlled via
 * `value`/`onValueChange`, or uncontrolled with `defaultValue`.
 */
const Calendar = React.forwardRef<HTMLDivElement, CalendarProps>(
  (
    {
      value,
      defaultValue,
      onValueChange,
      min,
      max,
      today,
      locale = 'en-US',
      weekStartsOn = 0,
      isDateDisabled,
      showOutsideDays = true,
      autoFocus = false,
      disabled = false,
      className,
      'aria-label': ariaLabel,
      ...props
    },
    ref
  ) => {
    const resolvedToday = today ?? todayKey();
    const [internal, setInternal] = React.useState(defaultValue ?? '');
    const selected = value ?? internal;
    const initial = selected || resolvedToday;
    const [view, setView] = React.useState(() => {
      const parts = parseDateKey(initial);
      return { year: parts?.year ?? 1970, month: parts?.month ?? 0 };
    });
    const [focusKey, setFocusKey] = React.useState(initial);
    const gridRef = React.useRef<HTMLDivElement | null>(null);
    const keyboardNav = React.useRef(false);

    // Follow an externally controlled value into its month.
    React.useEffect(() => {
      if (!selected) return;
      const parts = parseDateKey(selected);
      if (parts) setView({ year: parts.year, month: parts.month });
      setFocusKey(selected);
    }, [selected]);

    const weeks = React.useMemo(
      () => calendarWeeks(view.year, view.month, weekStartsOn),
      [view.year, view.month, weekStartsOn]
    );
    const weekdays = React.useMemo(
      () => weekdayLabels(locale, weekStartsOn),
      [locale, weekStartsOn]
    );

    const blocked = React.useCallback(
      (key: string) =>
        disabled ||
        Boolean((min && key < min) || (max && key > max)) ||
        Boolean(isDateDisabled?.(key)),
      [disabled, isDateDisabled, max, min]
    );

    const choose = (key: string) => {
      if (blocked(key)) return;
      if (value === undefined) setInternal(key);
      setFocusKey(key);
      onValueChange?.(key);
    };

    const onGridKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
      const move = MOVES[event.key];
      if (!move) return;
      event.preventDefault();
      const next = moveDateKey(focusKey, move, weekStartsOn);
      const parts = parseDateKey(next);
      if (parts) setView({ year: parts.year, month: parts.month });
      setFocusKey(next);
      keyboardNav.current = true;
    };

    // Roving tabindex only means something if the caret moves with it: after a
    // keyboard move, focus the day that owns the tab stop in the new view.
    React.useEffect(() => {
      if (!keyboardNav.current) return;
      const target = gridRef.current?.querySelector<HTMLButtonElement>(`[data-date="${focusKey}"]`);
      keyboardNav.current = false;
      target?.focus();
    }, [focusKey, view.year, view.month]);

    // Keep one tabbable day: the active one when visible, otherwise the first.
    const visibleKeys = weeks.flat().filter((day) => day.inMonth);
    const tabbable = visibleKeys.some((day) => day.key === focusKey)
      ? focusKey
      : (visibleKeys[0]?.key ?? '');

    React.useEffect(() => {
      if (!autoFocus) return;
      const timer = setTimeout(() => {
        gridRef.current
          ?.querySelector<HTMLButtonElement>(`[data-date="${tabbable}"]`)
          ?.focus();
      }, 0);
      return () => clearTimeout(timer);
    }, [autoFocus, tabbable, view.year, view.month]);

    const monthName = monthLabel(view.year, view.month, locale);

    return (
      <div
        ref={ref}
        className={cn('w-72 select-none', className)}
        data-disabled={disabled ? '' : undefined}
        {...props}
      >
        <div className="mb-2 flex items-center justify-between gap-2">
          <Button
            type="button"
            variant="ghost"
            size="icon"
            aria-label="Previous month"
            disabled={disabled}
            onClick={() => setView(partsOf(addMonths(keyOf(view), -1)))}
          >
            ‹
          </Button>
          <div aria-live="polite" className="text-sm font-semibold text-foreground">
            {monthName}
          </div>
          <Button
            type="button"
            variant="ghost"
            size="icon"
            aria-label="Next month"
            disabled={disabled}
            onClick={() => setView(partsOf(addMonths(keyOf(view), 1)))}
          >
            ›
          </Button>
        </div>

        <div
          ref={gridRef}
          role="grid"
          aria-label={ariaLabel ?? monthName}
          onKeyDown={onGridKeyDown}
          className="flex flex-col gap-1"
        >
          <div role="row" className="grid grid-cols-7 gap-1 text-center text-xs text-muted-foreground">
            {weekdays.map((weekday) => (
              <span key={weekday} role="columnheader" aria-label={weekday} className="py-1">
                {weekday}
              </span>
            ))}
          </div>

          {weeks.map((week) => (
            <div key={week[0]?.key} role="row" className="grid grid-cols-7 gap-1">
              {week.map((day) => {
                const isSelected = day.key === selected;
                const isToday = day.key === resolvedToday;
                const isBlocked = blocked(day.key);
                const hidden = !day.inMonth && !showOutsideDays;

                if (hidden) {
                  return (
                    <div key={day.key} role="gridcell" aria-hidden="true" className="h-9 w-9" />
                  );
                }

                return (
                  <div
                    key={day.key}
                    role="gridcell"
                    aria-selected={isSelected}
                    className="flex justify-center"
                  >
                    <Button
                      type="button"
                      size="sm"
                      variant={isSelected ? 'primary' : 'ghost'}
                      data-date={day.key}
                      tabIndex={day.key === tabbable ? 0 : -1}
                      aria-current={isToday ? 'date' : undefined}
                      aria-disabled={isBlocked || undefined}
                      aria-label={formatDateLabel(day.key, locale)}
                      className={cn(
                        'h-9 w-9 p-0 font-normal',
                        !day.inMonth && 'text-muted-foreground/80',
                        isBlocked && 'cursor-not-allowed opacity-40',
                        isToday && !isSelected && 'ring-1 ring-primary'
                      )}
                      onClick={() => choose(day.key)}
                    >
                      {day.day}
                    </Button>
                  </div>
                );
              })}
            </div>
          ))}
        </div>
      </div>
    );
  }
);
Calendar.displayName = 'Calendar';

function keyOf(view: { year: number; month: number }): string {
  return `${view.year}-${String(view.month + 1).padStart(2, '0')}-01`;
}

function partsOf(key: string): { year: number; month: number } {
  const parts = parseDateKey(key);
  return { year: parts?.year ?? 1970, month: parts?.month ?? 0 };
}

export { Calendar };

{
  "id": "calendar",
  "name": "Calendar",
  "tier": "organism",
  "description": "Month grid with ISO date keys, min/max bounds and full keyboard navigation.",
  "designIntent": "A native date input renders browser chrome that cannot be themed and differs per browser. Calendar is the visible grid behind a date field: controlled by ISO strings so a timezone cannot shift the chosen day, keyboard-operable cell by cell, and usable standalone or inside a Popover.",
  "props": [
    {
      "name": "value",
      "type": "string",
      "required": false,
      "description": "Selected day as `YYYY-MM-DD` (controlled)."
    },
    {
      "name": "defaultValue",
      "type": "string",
      "required": false,
      "description": "Initial day when uncontrolled."
    },
    {
      "name": "onValueChange",
      "type": "(value: string) => void",
      "required": false,
      "description": "Fired with the ISO key when a day is chosen."
    },
    {
      "name": "min",
      "type": "string",
      "required": false,
      "description": "Earliest selectable day, inclusive."
    },
    {
      "name": "max",
      "type": "string",
      "required": false,
      "description": "Latest selectable day, inclusive."
    },
    {
      "name": "today",
      "type": "string",
      "required": false,
      "description": "Overrides the highlighted today, for deterministic rendering."
    },
    {
      "name": "locale",
      "type": "string",
      "required": false,
      "defaultValue": "en-US",
      "description": "BCP-47 locale for month and weekday labels."
    },
    {
      "name": "weekStartsOn",
      "type": "0 | 1",
      "required": false,
      "defaultValue": "0",
      "description": "0 starts the week on Sunday, 1 on Monday."
    },
    {
      "name": "isDateDisabled",
      "type": "(value: string) => boolean",
      "required": false,
      "description": "Blocks individual days beyond min/max."
    },
    {
      "name": "showOutsideDays",
      "type": "boolean",
      "required": false,
      "defaultValue": "true",
      "description": "Show leading/trailing days from neighbouring months."
    },
    {
      "name": "autoFocus",
      "type": "boolean",
      "required": false,
      "defaultValue": "false",
      "description": "Focus the active day on mount, for popover use."
    },
    {
      "name": "disabled",
      "type": "boolean",
      "required": false,
      "description": "Disables every day and the month controls."
    },
    {
      "name": "className",
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    },
    {
      "name": "aria-label",
      "type": "string",
      "required": false,
      "description": "Overrides the grid label (defaults to the month name)."
    }
  ],
  "examples": [
    {
      "title": "Controlled calendar",
      "code": "<Calendar value={date} onValueChange={setDate} min=\"2026-01-01\" max=\"2026-12-31\" />",
      "description": "ISO strings in and out."
    },
    {
      "title": "Monday-first with blocked days",
      "code": "<Calendar weekStartsOn={1} locale=\"es-ES\" isDateDisabled={(d) => d.endsWith('-01')} />",
      "description": "Locale-aware week start and a predicate for holidays."
    }
  ],
  "antiPatterns": [
    {
      "title": "Don't store Date objects",
      "explanation": "A Date crossing a timezone boundary can land on the previous or next day. Keep ISO `YYYY-MM-DD` keys until you need to format them.",
      "example": "// Avoid\nonValueChange={(d) => setDate(d.toISOString())}\n\n// Prefer\nonValueChange={setDateKey}"
    },
    {
      "title": "Don't disable days by removing them",
      "explanation": "Removing cells breaks the grid rhythm and keyboard movement. Mark them with min/max/isDateDisabled so they stay visible."
    }
  ],
  "accessibility": [
    {
      "feature": "Grid semantics",
      "implementation": "role=grid with rows, columnheaders and gridcells; the month label is announced and polite.",
      "userRequirements": "Provide aria-label when several calendars share a page."
    },
    {
      "feature": "Keyboard",
      "implementation": "Arrows move by day/week, Home/End jump to week bounds, PageUp/PageDown change month, Enter/Space selects.",
      "userRequirements": "One tab stop; roving tabindex keeps the grid compact."
    },
    {
      "feature": "Selection state",
      "implementation": "aria-selected on the gridcell and aria-current=\"date\" for today.",
      "userRequirements": "Do not communicate selection by colour alone."
    }
  ],
  "contentGuidelines": [
    {
      "contentType": "Day labels",
      "guidelines": [
        "Use the full date as the accessible name",
        "Keep visible cells to the day number"
      ],
      "goodExamples": [
        "13"
      ],
      "badExamples": [
        "Nov 13"
      ]
    }
  ],
  "compositionRules": [
    {
      "component": "Popover",
      "relationship": "Wrap Calendar in PopoverContent for a date field",
      "example": "<PopoverContent><Calendar autoFocus /></PopoverContent>"
    },
    {
      "component": "DatePickerPopover",
      "relationship": "Use DatePickerPopover when the field and panel should ship together",
      "example": "<DatePickerPopover value={date} onValueChange={setDate} />"
    }
  ],
  "relatedComponents": [
    "DatePicker",
    "DatePickerPopover",
    "Popover",
    "DateRangePicker"
  ],
  "package": "@slipstream-ui/core",
  "importPath": "@slipstream-ui/core",
  "version": "0.12.1",
  "sourceDir": "calendar",
  "exportName": "Calendar"
}
